head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[selectbox > M > removeAll]<br/>컴포넌트에 정의된 전체 아이템을 제거합니다.",
    "validation" : [                        
        "아이템이 BindItemSet 으로 정의된 경우 DataCollection 에 반영되지 않습니다.",
        "exceptLabel(필수) 파라미터로 allOption, chooseOption 속성으로 추가된 아이템은 제거에서 제외할지 여부를 설정합니다.",
        "exceptLabel(필수) 파라미터를 미설정 시 allOption, chooseOption 속성으로 추가된 아이템도 함께 제거합니다.",
        "exceptLabel(필수) 파라미터를 true 로 설정 시 allOption, chooseOption 속성으로 추가된 아이템은 제거하지 않고 유지합니다.",
        "exceptLabel(필수) 파라미터를 false 로 설정 시 allOption, chooseOption 속성으로 추가된 아이템도 함께 제거합니다.",
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }    

    let properties = {
        allOption : true,
        chooseOption : true,
    }

    let cList = $c.gcm.createCList(properties)    

    // target 생성    
    $c.gcm.createLabel('label="removeAll 후 selectbox 클릭하여 아이템 리스트 오픈 시도 후  text 확인"', '', 'label1');
    $c.gcm.createBasicSelectBox(cList);
}



scwin.btn_getDataList_onclick = function (e) {
	// let rsData  = dlt_ref.getAllJSON();
    let rsData = gdl_selectbox.getAllJSON();

    for(var i = 0; i < rsData.length; i++) {        
        wf_body_bottom.getObj("scwin").setReturnValue("label 값 : " + rsData[i].label);
    }
};



scwin.btn_removeAll_onclick = function (e) {
    let exceptLabel = par_exceptLabel.getText();

    if (exceptLabel == "true")
        target1.removeAll(true);
    else if ("false")
        target1.removeAll(false);
    else
        target1.removeAll();
};



scwin.btn_getText_onclick = function (e) {
    let rtn = '';
    rtn = target1.render.textContent;

    wf_body_bottom.getObj("scwin").setReturnValue("selectbox 의 label : " + rtn);    


    let comp = "target1_itemTable_main";
    let targetElements = document.querySelectorAll('[id*='+comp+']');

    if (targetElements.length == 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("아이템 정보 없음");
        return;
    }

    let tds = targetElements[0].querySelectorAll('td.w2table_sb_col');

    // 각 td 요소의 visible 확인
    tds.forEach((td, index) => {   
        let itemLabel = td.textContent;
        wf_body_bottom.getObj("scwin").setReturnValue("item index=" + index + " 의 label : " + itemLabel);	
    });	
};
